	private static Projection localProducer(boolean alias) {
		String sourceName = alias ? "seed" : "g";
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of(sourceName));
		values.setBindingSets(List.of(binding(sourceName, RDF4J.NIL), binding(sourceName, RDF4J.NIL),
				binding(sourceName, SESAME.NIL), binding(sourceName, G1), EmptyBindingSet.getInstance()));
		TupleExpr left = alias ? new Extension(values, new ExtensionElem(Var.of("seed"), "g")) : values;
		StatementPattern right = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
				Var.of("predicate", P, true, true), Var.of("x"), Var.of("g"));
		Lateral lateral = new Lateral(left, right, Set.of("g"));
		ProjectionElemList projection = new ProjectionElemList(new ProjectionElem("g"), new ProjectionElem("x"),
				new ProjectionElem("frame"));
		if (alias) {
			projection.addElement(new ProjectionElem("seed"));
		}
		return new Projection(lateral, projection, false);
	}

	private static List<Map<String, Value>> localExpected(boolean alias, boolean frame) {
		List<Map<String, Value>> rows = new ArrayList<>();
		rows.add(localRow(RDF4J.NIL, A, alias ? RDF4J.NIL : null, frame));
		rows.add(localRow(RDF4J.NIL, A, alias ? RDF4J.NIL : null, frame));
		rows.add(localRow(SESAME.NIL, B, alias ? SESAME.NIL : null, frame));
		rows.add(localRow(G1, Z, alias ? G1 : null, frame));
		rows.add(localRow(RDF4J.NIL, C, null, frame));
		rows.add(localRow(SESAME.NIL, D, null, frame));
		rows.add(localRow(G1, Z, null, frame));
		return rows;
	}

	private static Map<String, Value> localRow(Value graph, Value object, Value seed, boolean frame) {
		Map<String, Value> row = new HashMap<>();
		row.put("g", graph);
		row.put("x", object);
		if (seed != null) {
			row.put("seed", seed);
		}
		if (frame) {
			row.put("frame", FRAME);
		}
		return Map.copyOf(row);
	}

	@Test
	void parsedOrdinaryGraphEnumeratesNamedNilContexts() {
		String values = " VALUES ?g { " + token(RDF4J.NIL) + " " + token(RDF4J.NIL) + " "
				+ token(SESAME.NIL) + " " + token(G1) + " UNDEF } ";
		String body = " GRAPH ?g { ?g " + token(P) + " ?x } ";
		String ordinary = "SELECT ?g ?x WHERE { " + values + body + " }";
		List<Map<String, Value>> ordinaryExpected = List.of(
				Map.of("g", RDF4J.NIL, "x", C), Map.of("g", RDF4J.NIL, "x", C),
				Map.of("g", RDF4J.NIL, "x", C), Map.of("g", SESAME.NIL, "x", D),
				Map.of("g", SESAME.NIL, "x", D), Map.of("g", G1, "x", Z), Map.of("g", G1, "x", Z));
		assertParsedRows(ordinary, null, EmptyBindingSet.getInstance(), ordinaryExpected);
	}

	@Test
	void parsedLateralGraphMakesEachSelectorAnInvocationInput() {
		String values = " VALUES ?g { " + token(RDF4J.NIL) + " " + token(RDF4J.NIL) + " "
				+ token(SESAME.NIL) + " " + token(G1) + " UNDEF } ";
		String body = " GRAPH ?g { ?g " + token(P) + " ?x } ";
		String lateral = "SELECT ?g ?x WHERE { " + values + " LATERAL { " + body + " } }";
		assertParsedRows(lateral, null, EmptyBindingSet.getInstance(), localExpected(false, false));
	}

