	@ParameterizedTest(name = "parsed LATERAL distinct context alias={0}")
	@ValueSource(booleans = { false, true })
	void parsedLateralCanFeedAContextSlot(boolean alias) throws Exception {
		String name = alias ? "seed" : "g";
		String values = " VALUES ?" + name + " { " + token(RDF4J.NIL) + " " + token(RDF4J.NIL) + " "
				+ token(SESAME.NIL) + " " + token(G1) + " UNDEF } ";
		String bind = alias ? " BIND(?seed AS ?g) " : "";
		String query = "SELECT ?g ?s ?x ?seed ?frame WHERE { " + values + bind
				+ " LATERAL { GRAPH ?g { ?s " + token(P) + " ?x } } }";
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"parsed local NIL context producer", Query.QueryType.TUPLE, "nestedLoop");
		try {
			LmdbNativeEvaluationStrategy strategy = nativeStrategy(null);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			List<BindingSet> inputs = List.of(EmptyBindingSet.getInstance(), binding("frame", FRAME));
			SoftAssertions genericChecks = new SoftAssertions();
			for (BindingSet input : inputs) {
				List<Map<String, Value>> expected = distinctExpected(alias, input.hasBinding("frame"));
				Observation generic = evaluate(new DefaultEvaluationStrategy(triples, null).precompile(
						projection(parsed(query)), context), null, input);
				System.out.printf("parsed-local generic alias=%s input=%s result=%s%n", alias, input, generic);
				genericChecks.assertThat(generic.rows())
						.as("parsed generic LATERAL alias=%s", alias)
						.containsExactlyInAnyOrderElementsOf(expected);
			}
			genericChecks.assertAll();
			Projection logical = projection(parsed(query));
			assertThat(graphs(logical)).hasSize(1);
			mark(logical);
			NativeGraphFusion.Prepared prepared = NativeGraphFusion.prepare(logical, null, strategy);
			TupleExpr physical = prepared.expression();
			mark(physical);
			// Both inputs below leave g unbound at entry, so the original alias guard selects this fused recipe.
			// The inspected recipe is the compiler's result for the real parsed GRAPH lowering.
			QueryEvaluationStep physicalStep = LmdbNativeAggregateCompiler.tryCompile(physical, context, strategy,
					source);
			boolean direct = physicalStep instanceof NativeRowsStep rows && rows.arg instanceof LateralPlan lateral
					&& lateral.right instanceof PatternPlan && (alias
							? lateral.left instanceof ExtensionPlan extension && extension.arg instanceof ValuesPlan
							: lateral.left instanceof ValuesPlan);
			if (direct) {
				LateralPlan lateral = (LateralPlan) ((NativeRowsStep) physicalStep).arg;
				PatternPlan pattern = (PatternPlan) lateral.right;
				assertThat(graphs(physical)).as("the inspected recipe comes from actual GRAPH fusion").isEmpty();
				assertThat(prepared.guardedSelectors()).contains("g");
				assertThat(pattern.c.slot).isNotNegative().isNotEqualTo(pattern.s.slot);
				assertThat(lateral.rightInputMask & (1L << pattern.c.slot))
						.as("the parsed LATERAL passes g into its physical context slot")
						.isNotZero();
				assertThat(lateral.left.producedMask() & (1L << pattern.c.slot))
						.as("the accepted left producer can bind that context slot")
						.isNotZero();
				SlotPlan valuesPlan = alias ? ((ExtensionPlan) lateral.left).arg : lateral.left;
				assertThat(((ValuesPlan) valuesPlan).rows).hasSize(5);
				assertThat(((ValuesPlan) valuesPlan).bindsAllSlotsEveryRow).isFalse();
			} else {
				System.out.printf("parsed-local alias=%s physical-shape=unavailable guards=%s step=%s plan=%s%n",
						alias, prepared.guardedSelectors(), physicalStep == null ? "null" : physicalStep.getClass(),
						describe(physicalStep));
			}
			QueryEvaluationStep logicalStep = strategy.precompile(logical, context);
			SoftAssertions softly = new SoftAssertions();
			for (BindingSet input : inputs) {
				List<Map<String, Value>> expected = distinctExpected(alias, input.hasBinding("frame"));
				Observation actual = evaluate(logicalStep, logical, input);
				softly.assertThat(actual.rows())
						.as("parsed native LATERAL alias=%s", alias)
						.containsExactlyInAnyOrderElementsOf(expected);
				System.out.printf("parsed-local alias=%s input=%s logicalPlan=%s logical=%s%n", alias, input,
						describe(logicalStep), actual);
				if (direct) {
					List<LmdbNativeDecisionTestAccess.Selected> decisions = new ArrayList<>();
					Observation lowered;
					try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(decisions)) {
						lowered = evaluate(physicalStep, logical, input);
					}
					System.out.printf("parsed-local alias=%s input=%s physicalPlan=%s decisions=%s actual=%s%n",
							alias, input, describe(physicalStep), decisions, lowered);
					softly.assertThat(lowered.rows())
							.as("the compiler-returned physical LATERAL alias=%s", alias)
							.containsExactlyInAnyOrderElementsOf(expected);
					softly.assertThat(lowered.invocations()).as("the physical LATERAL opens native work").isPositive();
					softly.assertThat(lowered.runtime()).as("the physical LATERAL executes").contains("executed");
					softly.assertThat(decisions)
							.as("this physical invocation opens nestedLoop")
							.anyMatch(choice -> choice.target() == physical && choice.point().equals("ROW")
									&& choice.id().equals("nestedLoop"));
				}
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

	private static List<Map<String, Value>> distinctExpected(boolean alias, boolean frame) {
		List<Map<String, Value>> rows = new ArrayList<>();
		for (int duplicate = 0; duplicate < 2; duplicate++) {
			rows.add(distinctRow(RDF4J.NIL, RDF4J.NIL, A, alias ? RDF4J.NIL : null, frame));
			rows.add(distinctRow(RDF4J.NIL, SESAME.NIL, B, alias ? RDF4J.NIL : null, frame));
		}
		rows.add(distinctRow(SESAME.NIL, RDF4J.NIL, A, alias ? SESAME.NIL : null, frame));
		rows.add(distinctRow(SESAME.NIL, SESAME.NIL, B, alias ? SESAME.NIL : null, frame));
		rows.add(distinctRow(G1, G1, Z, alias ? G1 : null, frame));
		rows.add(distinctRow(G1, RDF4J.NIL, E, alias ? G1 : null, frame));
		rows.add(distinctRow(RDF4J.NIL, RDF4J.NIL, C, null, frame));
		rows.add(distinctRow(SESAME.NIL, SESAME.NIL, D, null, frame));
		rows.add(distinctRow(G1, G1, Z, null, frame));
		rows.add(distinctRow(G1, RDF4J.NIL, E, null, frame));
		return rows;
	}

	private static Map<String, Value> distinctRow(Value graph, Value subject, Value object, Value seed, boolean frame) {
		Map<String, Value> row = new HashMap<>(localRow(graph, object, seed, frame));
		row.put("s", subject);
		return Map.copyOf(row);
	}

	private record ProjectionCase(String[] sources, String[] targets, Map<String, Value> expected,
			boolean suppliedG, boolean suppliedH) {
	}

	private static ProjectionCase projectionCase(String name) {
		return switch (name) {
		case "same" -> new ProjectionCase(new String[] { "g" }, new String[] { "g" },
				Map.of("g", A, "h", B), false, true);
		case "equal" -> new ProjectionCase(new String[] { "x" }, new String[] { "g" },
				Map.of("g", A, "h", B), false, true);
		case "absent" -> new ProjectionCase(new String[] { "missing" }, new String[] { "g" },
				Map.of("g", A, "h", B), true, true);
		case "duplicate" -> new ProjectionCase(new String[] { "h", "missing" }, new String[] { "g", "g" },
				Map.of("g", B, "h", B), false, true);
		case "alias" -> new ProjectionCase(new String[] { "x" }, new String[] { "alias" },
				Map.of("g", A, "h", B, "alias", A), true, true);
		default -> throw new IllegalArgumentException(name);
		};
	}

	private static Projection nestedProjection(TupleExpr child, ProjectionCase projectionCase) {
		ProjectionElemList elements = new ProjectionElemList();
		for (int i = 0; i < projectionCase.sources().length; i++) {
			elements.addElement(new ProjectionElem(projectionCase.sources()[i], projectionCase.targets()[i]));
		}
		Projection inner = new Projection(child, elements, false);
		new Projection(inner, new ProjectionElemList(new ProjectionElem("g"), new ProjectionElem("h")), false);
		return inner;
	}

	private static StatementPattern projectionPattern() {
		return new StatementPattern(Var.of("x"), Var.of("p", FIXED_P, true, true), Var.of("o", A, true, true));
	}

	private static MutableBindingSet projectionCaller() {
		MutableBindingSet caller = GraphFrameBindings.supply(new QueryBindingSet(), "g", A);
		return GraphFrameBindings.supply(caller, "h", B);
	}

	private static Map<String, Value> bindingsMap(BindingSet bindings) {
		Map<String, Value> result = new HashMap<>();
		bindings.forEach(binding -> result.put(binding.getName(), binding.getValue()));
		return Map.copyOf(result);
	}

	private static List<BindingSet> projectionRows(QueryEvaluationStep step, BindingSet input) {
		List<BindingSet> rows = new ArrayList<>();
		try (var result = step.evaluate(input)) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static void checkProjectionRows(SoftAssertions softly, String label, ProjectionCase expected,
			BindingSet input, List<BindingSet> rows, BindingFrameReplay.Domain replay) {
		softly.assertThat(rows).as("%s row count", label).hasSize(1);
		for (BindingSet row : rows) {
			softly.assertThat(bindingsMap(row)).as("%s exact projected mapping", label).isEqualTo(expected.expected());
			softly.assertThat(GraphFrameBindings.isSupplied(row, "g"))
					.as("%s g authority", label)
					.isEqualTo(expected.suppliedG());
			softly.assertThat(GraphFrameBindings.isSupplied(row, "h"))
					.as("%s h authority", label)
					.isEqualTo(expected.suppliedH());
			softly.assertThat(GraphFrameBindings.isSupplied(row, "alias")).as("%s alias authority", label).isFalse();
			softly.assertThat(BindingFrameBindings.from(row))
					.as("%s binding frame", label)
					.isSameAs(BindingFrameBindings.from(input));
			softly.assertThat(BindingFrameReplay.domain(row)).as("%s live replay domain", label).isSameAs(replay);
		}
		softly.assertThat(bindingsMap(input)).as("%s input values", label).isEqualTo(Map.of("g", A, "h", B));
		softly.assertThat(GraphFrameBindings.isSupplied(input, "g")).as("%s caller g authority", label).isTrue();
		softly.assertThat(GraphFrameBindings.isSupplied(input, "h")).as("%s caller h authority", label).isTrue();
		softly.assertThat(BindingFrameReplay.domain(input)).as("%s caller replay", label).isSameAs(replay);
	}

	@ParameterizedTest(name = "nested projection {0}")
	@ValueSource(strings = { "same", "equal", "absent", "duplicate", "alias" })
	void nestedProjectionWritesOnlyRevokeTheirTarget(String name) {
		ProjectionCase projectionCase = projectionCase(name);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"nested projection graph provenance", Query.QueryType.TUPLE, "nestedLoop");
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			BindingSet input = BindingFrameBindings.withReplay(projectionCaller(), invocation.root, context);
			SoftAssertions softly = new SoftAssertions();
			QueryBindingSet produced = new QueryBindingSet(input);
			produced.setBinding("x", A);
			Projection genericProbe = nestedProjection(new SingletonSet(), projectionCase);
			List<BindingSet> projected = new ArrayList<>();
			try (ProjectionIterator iterator = new ProjectionIterator(genericProbe,
					new SingletonIteration<>(produced), input, context)) {
				while (iterator.hasNext()) {
					projected.add(iterator.next());
				}
			}
			checkProjectionRows(softly, "generic projection iterator", projectionCase, input, projected,
					invocation.root);
			BindingSet direct = NativeBindingSetProjectionStep.project(produced, input, projectionCase.sources(),
					projectionCase.targets(), true);
			checkProjectionRows(softly, "native projection copy", projectionCase, input, List.of(direct),
					invocation.root);

			Projection generic = nestedProjection(projectionPattern(), projectionCase);
			QueryEvaluationStep genericStep = new DefaultEvaluationStrategy(triples, null).precompile(generic, context);
			checkProjectionRows(softly, "generic statement projection", projectionCase, input,
					projectionRows(genericStep, input), invocation.root);

			Projection nativeExpression = nestedProjection(projectionPattern(), projectionCase);
			mark(nativeExpression);
			QueryEvaluationStep step = nativeStrategy(null).precompile(nativeExpression, context);
			NativeRowsStep capability = BindingFrameBindings.unframedCapability(step, NativeRowsStep.class);
			List<BindingSet> actual = projectionRows(step, input);
			checkProjectionRows(softly, "native-enabled statement projection", projectionCase, input, actual,
					invocation.root);
			String path = nativeExpression.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
			String runtime = nativeExpression.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			long invocations = Math.max(0L, nativeExpression.getLongMetricActual("nativeInvocationsActual"));
			if (capability != null && invocations > 0 && runtime != null && runtime.contains("executed")
					&& (path == null || !path.contains("genericFallback"))) {
				softly.assertThat(capability.projectionBoundary).as("%s is a semantic projection", name).isTrue();
				softly.assertThat(invocations).as("%s executed native rows", name).isPositive();
			} else {
				System.out.printf("nested projection %s: native execution unavailable, path=%s count=%s%n", name, path,
						invocations);
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

