	private static List<BindingSet> physicalProjectionRows(NativeResultCursor cursor) {
		List<BindingSet> rows = new ArrayList<>();
		try (cursor) {
			NativeResultRow row;
			while ((row = cursor.next()) != null) {
				rows.add(row.toBindingSet());
			}
		}
		return rows;
	}

