	private static void checkSelectedProjection(SoftAssertions softly, String label, BindingSet input,
			List<BindingSet> rows, boolean expectHiddenH) {
		softly.assertThat(rows).as("%s row count", label).hasSize(1);
		for (BindingSet row : rows) {
			softly.assertThat(bindingsMap(row)).as("%s exact projected mapping", label).isEqualTo(Map.of("g", A));
			softly.assertThat(GraphFrameBindings.isSupplied(row, "g"))
					.as("%s projected g authority", label)
					.isFalse();
			if (expectHiddenH) {
				Map<String, Value> parameters = new HashMap<>();
				GraphFrameBindings.from(row).visit(parameters::put);
				softly.assertThat(parameters)
						.as("%s preserves unrelated private h", label)
						.containsEntry("h", B)
						.doesNotContainKey("g");
			}
		}
		softly.assertThat(bindingsMap(input)).as("%s input mapping", label).isEqualTo(Map.of("g", A, "h", B));
		softly.assertThat(GraphFrameBindings.isSupplied(input, "g")).as("%s caller g", label).isTrue();
		softly.assertThat(GraphFrameBindings.isSupplied(input, "h")).as("%s caller h", label).isTrue();
	}

	@Test
	void selectedPhysicalProjectionAndSameEvaluationWorkerKeepTheWriteBoundary() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet input = projectionCaller();
		SoftAssertions softly = new SoftAssertions();
		softly.assertThat(BindingFrameBindings.hasFrame(input))
				.as("the physical capability entry is unframed")
				.isFalse();
		QueryRoot genericRoot = selectedProjectionRoot();
		checkSelectedProjection(softly, "generic selected projection", input,
				projectionRows(new DefaultEvaluationStrategy(triples, null).precompile(genericRoot, context), input),
				false);
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"selected physical projection provenance", Query.QueryType.TUPLE, "nestedLoop");
		try {
			LmdbNativeEvaluationStrategy strategy = nativeStrategy(null);
			QueryRoot root = selectedProjectionRoot();
			mark(root);
			QueryEvaluationStep prepared = strategy.precompile(root, context);
			NativeRowsStep rows = BindingFrameBindings.unframedCapability(prepared, NativeRowsStep.class);
			List<BindingSet> actual = projectionRows(prepared, input);
			String path = root.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
			String runtime = root.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			long invocations = Math.max(0L, root.getLongMetricActual("nativeInvocationsActual"));
			boolean openedNative = rows != null && invocations > 0 && runtime != null && runtime.contains("executed")
					&& (path == null || !path.contains("genericFallback"));
			checkSelectedProjection(softly, "native-enabled selected projection", input,
					actual, openedNative);
			if (rows == null) {
				System.out.println("selected projection: native row capability declined");
			} else {
				softly.assertThat(rows.projectionBoundary).as("prepared rows retain the projection boundary").isTrue();
				NativeLmdbQuerySource evaluationSource = rows.evaluationSource(input);
				if (!(evaluationSource instanceof SyntheticValueSource evaluation)) {
					System.out.println("selected projection: evaluation-scoped physical source unavailable");
				} else {
					try (SyntheticValueSource.EvaluationScope ignored = SyntheticValueSource
							.attachEvaluation(evaluation)) {
						NativePhysicalResultPlan selected = rows.physicalPlan(input);
						if (selected == null || !(selected.step() instanceof NativeResultStep selectedStep)) {
							System.out.println("selected projection: physical recipe declined");
						} else {
							root.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
							checkSelectedProjection(softly, "selected physical projection", input,
									physicalProjectionRows(selectedStep.evaluateNative(input)), true);
							softly.assertThat(LmdbNativeExplain.hasExecutionPath(root, "nativePhysicalCells"))
									.as("the selected recipe opened physical cells")
									.isTrue();
							if (selected.rebindRecipe() == null || selected.outputEvidence() == null) {
								System.out.println("selected projection: worker rebind recipe unavailable");
							} else {
								QueryRoot workerRoot = root.clone();
								NativeGraphFusion.preserveLexicalScopes(root, workerRoot);
								NativeValuePositionAnalysis positions = strategy.copyValuePositions(root, workerRoot);
								mark(workerRoot);
								NativeScalarPlan.WorkerContext worker = NativeScalarPlan.WorkerContext.forSource(
										evaluation,
										context);
								LmdbNativeEvaluationStrategy workerStrategy = strategy.forWorker(worker.source());
								QueryEvaluationContext workerContext = new BindingSetQueryEvaluationContext(
										evaluation.executionContext().genericContext(context, workerStrategy));
								QueryEvaluationStep workerPrepared = workerStrategy.withValuePositions(positions,
										() -> LmdbNativeAggregateCompiler.tryCompileSemanticSubquery(workerRoot,
												workerContext, workerStrategy, worker.source(), Set.of(), Set.of()));
								NativeRowsStep workerRows = workerPrepared == null ? null
										: BindingFrameBindings.unframedCapability(workerPrepared, NativeRowsStep.class);
								if (workerRows == null) {
									System.out.println("selected projection: worker row preparation declined");
								} else {
									softly.assertThat(workerRows)
											.as("the worker has an independent prepared step")
											.isNotSameAs(rows);
									softly.assertThat(workerRows.projectionBoundary)
											.as("worker preparation retains the projection boundary")
											.isTrue();
									NativePhysicalResultPlan rebound = selected.rebind(workerRows, worker, input);
									if (rebound == null || !(rebound.step() instanceof NativeResultStep reboundStep)) {
										System.out
												.println("selected projection: same-evaluation worker rebind declined");
									} else {
										root.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
										workerRoot.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH,
												null);
										checkSelectedProjection(softly, "rebound worker projection", input,
												physicalProjectionRows(reboundStep.evaluateNative(input)), true);
										boolean workerOpened = LmdbNativeExplain.hasExecutionPath(workerRoot,
												"nativePhysicalCells");
										softly.assertThat(workerOpened)
												.as("the rebound worker opened physical cells")
												.isTrue();
									}
								}
							}
						}
					} finally {
						evaluation.executionContext().close();
					}
				}
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

	@ParameterizedTest(name = "active context {0}, optimizer={1}, negative={2}")
	@CsvSource({ "direct,false,false", "direct,true,false", "graph,false,false", "graph,true,false",
			"union,false,false", "union,true,false", "direct,false,true", "direct,true,true" })
	void activeGraphPartialFilterKeepsMatchingAlternatives(String shape, boolean optimized, boolean negative) {
		List<IRI> candidates = negative ? List.of(D) : List.of(E, Z, C);
		BindingSet suppliedInput = GraphFrameBindings.supply(new QueryBindingSet(), "g", G1);
		List<BindingSet> inputs = List.of(EmptyBindingSet.getInstance(), binding("g", G1), suppliedInput);
		Projection genericExpression = activePartialQuery(shape, candidates);
		Projection nativeExpression = activePartialQuery(shape, candidates);
		if (optimized) {
			StandardQueryOptimizerPipeline.getFilterInValuesOptimizer()
					.optimize(genericExpression, null,
							EmptyBindingSet.getInstance());
			StandardQueryOptimizerPipeline.getFilterInValuesOptimizer()
					.optimize(nativeExpression, null,
							EmptyBindingSet.getInstance());
		}
		SoftAssertions softly = new SoftAssertions();
		softly.assertThat(GraphFrameBindings.isSupplied(suppliedInput, "g"))
				.as("caller starts with a supplied GRAPH binding")
				.isTrue();
		if (optimized) {
			checkExactValuesAnchor(softly, "generic", genericExpression, candidates);
			checkExactValuesAnchor(softly, "native", nativeExpression, candidates);
		}
		softly.assertThat(source.idOf(D))
				.as("the negative value exists in the source dictionary")
				.isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
		QueryEvaluationContext context = shape.equals("direct") ? activeGraphContext()
				: new QueryEvaluationContext.Minimal((Dataset) null);
		QueryEvaluationStep genericStep = new DefaultEvaluationStrategy(triples, null).precompile(genericExpression,
				context);
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"active graph partial filter", Query.QueryType.TUPLE, "nestedLoop");
		try {
			mark(nativeExpression);
			TupleExpr body = nativeExpression.getArg() instanceof Graph graph ? graph.getArg()
					: nativeExpression.getArg();
			mark(body);
			LmdbNativeEvaluationStrategy strategy = nativeStrategy(null);
			if (!shape.equals("direct")) {
				softly.assertThat(NativeGraphFusion.prepare(nativeExpression, null, strategy).expression())
						.as("the public GRAPH retains its active-context boundary")
						.isSameAs(nativeExpression);
			}
			long prepareBefore = LmdbNativeAggregateCompiler.FILTER_INTO_PATTERN_PUSHDOWNS.get();
			QueryEvaluationStep nativeStep = strategy.precompile(nativeExpression, context);
			long preparePushdowns = LmdbNativeAggregateCompiler.FILTER_INTO_PATTERN_PUSHDOWNS.get() - prepareBefore;
			NativeRowsStep rows = BindingFrameBindings.unframedCapability(nativeStep, NativeRowsStep.class);
			NativeBareRowsStep bare = BindingFrameBindings.unframedCapability(nativeStep, NativeBareRowsStep.class);
			for (BindingSet input : inputs) {
				Value inputGraph = input.getValue("g");
				boolean inputSupplied = GraphFrameBindings.isSupplied(input, "g");
				List<Map<String, Value>> expected = activePartialExpected(shape, negative, input.hasBinding("g"));
				MembershipObservation generic = observeMembership(genericStep, null, input);
				checkProjectedMembership(softly, "generic active partial", shape, input, inputGraph, inputSupplied,
						expected, generic);
				long bodyBefore = Math.max(0L, body.getLongMetricActual("nativeInvocationsActual"));
				long pushedBefore = LmdbNativeAggregateCompiler.FILTER_INTO_PATTERN_PUSHDOWNS.get();
				MembershipObservation actual = observeMembership(nativeStep, nativeExpression, input);
				long bodyInvocations = Math.max(0L, body.getLongMetricActual("nativeInvocationsActual")) - bodyBefore;
				long pushed = LmdbNativeAggregateCompiler.FILTER_INTO_PATTERN_PUSHDOWNS.get() - pushedBefore;
				String route = actual.invocations() > 0 && actual.runtime() != null
						&& actual.runtime().contains("executed")
								? "native-executed"
								: actual.path() != null && actual.path().contains("genericFallback")
										? "reported-generic-fallback"
										: rows != null || bare != null ? "native-accepted-unattributed"
												: "generic-or-wrapper";
				System.out.printf("active-partial shape=%s optimized=%s negative=%s input=%s generic=%s "
						+ "native=%s route=%s rows=%s bare=%s bodyInvocations=%s filterPushdowns=%s/%s%n", shape,
						optimized, negative, input, generic, actual, route,
						rows == null ? null : rows.arg.getClass().getSimpleName(),
						bare == null ? null : bare.arg.getClass().getSimpleName(), bodyInvocations, preparePushdowns,
						pushed);
				checkProjectedMembership(softly, "native active partial", shape, input, inputGraph, inputSupplied,
						expected, actual);
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

	private static QueryEvaluationContext activeGraphContext() {
		return new ActiveGraphQueryEvaluationContext(new QueryEvaluationContext.Minimal((Dataset) null),
				new QueryEvaluationContext.ActiveGraph(G1, G1));
	}

	private static Projection activePartialQuery(String shape, List<IRI> candidates) {
		StatementPattern contextual = partialPattern(true);
		TupleExpr input = contextual;
		if (shape.equals("union")) {
			Filter inner = new Filter(contextual, new Bound(Var.of("s")));
			inner.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
			input = new Union(partialPattern(false), inner);
		}
		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of("o"));
		for (IRI value : candidates) {
			condition.addArgument(new ValueConstant(value));
		}
		Filter filter = new Filter(input, condition);
		filter.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
		TupleExpr scoped = shape.equals("direct") ? filter : new Graph(Var.of("selector", G1, true, true), filter);
		return new Projection(scoped, new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("o"),
				new ProjectionElem("g")), false);
	}

	private static StatementPattern partialPattern(boolean context) {
		return new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS, Var.of("s"),
				Var.of("predicate", P, true, true), Var.of("o"), context ? Var.of("g") : null);
	}

	private static List<Map<String, Value>> activePartialExpected(String shape, boolean negative, boolean hasInput) {
		if (negative) {
			return List.of();
		}
		List<Map<String, Value>> expected = new ArrayList<>(List.of(
				Map.of("s", RDF4J.NIL, "o", E, "g", G1), Map.of("s", G1, "o", Z, "g", G1)));
		if (shape.equals("union")) {
			expected.add(hasInput ? Map.of("s", RDF4J.NIL, "o", E, "g", G1)
					: Map.of("s", RDF4J.NIL, "o", E));
			expected.add(hasInput ? Map.of("s", G1, "o", Z, "g", G1) : Map.of("s", G1, "o", Z));
		}
		return expected;
	}

	private static void checkExactValuesAnchor(SoftAssertions softly, String label, TupleExpr expression,
			List<IRI> candidates) {
		List<BindingSetAssignment> anchors = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				if (assignment.getLongMetricPlanned(TelemetryMetricNames.OPTIMIZER_EXACT_VALUES) == 1L) {
					anchors.add(assignment);
				}
			}
		});
		softly.assertThat(anchors).as("%s real optimizer-exact VALUES anchor", label).hasSize(1);
		if (anchors.size() == 1) {
			List<Value> actual = new ArrayList<>();
			anchors.get(0).getBindingSets().forEach(row -> actual.add(row.getValue("o")));
			softly.assertThat(actual)
					.as("%s exact optimizer values", label)
					.containsExactlyInAnyOrderElementsOf(candidates);
		}
	}

	@Test
	void ordinaryContextFilterRetainsNativeExecution() {
		List<IRI> candidates = List.of(E, Z, C);
		Projection genericExpression = activePartialQuery("direct", candidates);
		Projection nativeExpression = activePartialQuery("direct", candidates);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		List<Map<String, Value>> expected = List.of(Map.of("s", RDF4J.NIL, "o", E, "g", G1),
				Map.of("s", G1, "o", Z, "g", G1), Map.of("s", RDF4J.NIL, "o", C, "g", RDF4J.NIL));
		MembershipObservation generic = observeMembership(
				new DefaultEvaluationStrategy(triples, null).precompile(genericExpression, context), null,
				EmptyBindingSet.getInstance());
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"ordinary context filter", Query.QueryType.TUPLE, "nestedLoop");
		try {
			mark(nativeExpression);
			QueryEvaluationStep nativeStep = nativeStrategy(null).precompile(nativeExpression, context);
			MembershipObservation actual = observeMembership(nativeStep, nativeExpression,
					EmptyBindingSet.getInstance());
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(generic.rows())
					.as("ordinary generic control")
					.containsExactlyInAnyOrderElementsOf(expected);
			softly.assertThat(actual.rows())
					.as("ordinary native control")
					.containsExactlyInAnyOrderElementsOf(expected);
			softly.assertThat(BindingFrameBindings.unframedCapability(nativeStep, NativeRowsStep.class))
					.as("ordinary control retains a native row entry")
					.isNotNull();
			softly.assertThat(actual.invocations()).as("ordinary control native invocations").isPositive();
			softly.assertThat(actual.runtime()).as("ordinary control executed plan").contains("executed");
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

	@Test
	void leapfrogAdmissionRetainsOverlappingContextProducers() throws Exception {
		setProperty(LmdbNativeLeapfrogJoin.ENABLED_PROPERTY, "true");
		SimpleDataset selection = new SimpleDataset();
		selection.addDefaultGraph(G1);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(selection);
		TupleExpr genericExpression = new Projection(
				new Join(new Join(overlapPattern("a", "b"), overlapPattern("b", "c")),
						overlapPattern("c", "a")),
				new ProjectionElemList(new ProjectionElem("a"), new ProjectionElem("b"), new ProjectionElem("c"),
						new ProjectionElem("g")),
				false);
		List<Map<String, Value>> expected = List.of(Map.of("a", C, "b", C, "c", C, "g", G1));
		QueryEvaluationStep genericStep = new DefaultEvaluationStrategy(triples, selection, null)
				.precompile(genericExpression, context);
		MembershipObservation generic = observeMembership(genericStep, null, EmptyBindingSet.getInstance());
		MembershipObservation genericBound = observeMembership(genericStep, null, binding("g", G1));
		SoftAssertions softly = new SoftAssertions();
		softly.assertThat(generic.rows())
				.as("independent unbound overlap bag")
				.containsExactlyInAnyOrderElementsOf(expected);
		softly.assertThat(genericBound.rows())
				.as("independent bound overlap bag")
				.containsExactlyInAnyOrderElementsOf(expected);

		LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(context, nativeStrategy(selection), source);
		PatternPlan first = planner.compileStatementPattern(overlapPattern("a", "b"));
		PatternPlan second = planner.compileStatementPattern(overlapPattern("b", "c"));
		PatternPlan third = planner.compileStatementPattern(overlapPattern("c", "a"));
		softly.assertThat(first).as("first compiled pattern").isNotNull();
		softly.assertThat(second).as("second compiled pattern").isNotNull();
		softly.assertThat(third).as("third compiled pattern").isNotNull();
		int a = planner.slot("a");
		int b = planner.slot("b");
		int c = planner.slot("c");
		int g = planner.slot("g");
		planner.layout.freeze(planner.slotNames);
		if (first != null && second != null && third != null) {
			MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { first, second, third }, new MaskedFilter[0]);
			for (PatternPlan pattern : List.of(first, second, third)) {
				softly.assertThat(pattern.dynamicContext).as("the context capability is retained").isNotNull();
				if (pattern.dynamicContext != null) {
					softly.assertThat(pattern.dynamicContext.slot).isEqualTo(g);
				}
				softly.assertThat(pattern.producedMask() & (1L << g)).isNotZero();
			}
			softly.assertThatCode(() -> {
				RowState unbound = new RowState(source, planner.layout, EmptyBindingSet.getInstance());
				boolean unboundReady = LmdbNativeAggregateCompiler.initializeRow(unbound, EmptyBindingSet.getInstance(),
						source, planner.layout);
				softly.assertThat(unboundReady).as("unbound row seeded").isTrue();
				if (!unboundReady) {
					return;
				}
				softly.assertThatCode(() -> {
					LmdbNativeLeapfrogJoin.Shape shape = LmdbNativeLeapfrogJoin.shape(plan, unbound.boundMask());
					softly.assertThat(shape).as("three overlapping context-producing core patterns").isNotNull();
					if (shape != null) {
						softly.assertThat(shape.core()).hasSize(3);
						softly.assertThat(LmdbNativeLeapfrogJoin.permits(shape, unbound))
								.as("another core can produce the unbound context")
								.isFalse();
					}
					RowCursor declined = LmdbNativeLeapfrogJoin.tryOpen(plan, unbound);
					if (declined != null) {
						declined.close();
					}
					softly.assertThat(declined).as("overlap declines before opening").isNull();
				}).as("unbound overlap admission").doesNotThrowAnyException();
				softly.assertThatCode(() -> {
					RowCursor fallback = plan.open(unbound);
					softly.assertThat(fallback).as("ordinary fallback cursor").isNotNull();
					if (fallback != null) {
						softly.assertThat(overlapRows(fallback, unbound, a, b, c, g))
								.as("the ordinary fallback retains the matching row")
								.containsExactlyInAnyOrderElementsOf(expected);
					}
				}).as("unbound overlap result").doesNotThrowAnyException();
			}).as("unbound overlap setup").doesNotThrowAnyException();

			softly.assertThatCode(() -> {
				BindingSet input = binding("g", G1);
				RowState bound = new RowState(source, planner.layout, input);
				boolean boundReady = LmdbNativeAggregateCompiler.initializeRow(bound, input, source, planner.layout);
				softly.assertThat(boundReady).as("bound row seeded").isTrue();
				if (!boundReady) {
					return;
				}
				softly.assertThatCode(() -> {
					long openedBefore = LmdbNativeLeapfrogJoin.OPENED.get();
					RowCursor opened = LmdbNativeLeapfrogJoin.tryOpen(plan, bound);
					softly.assertThat(opened).as("an ordinary bound context admits leapfrog").isNotNull();
					softly.assertThat(LmdbNativeLeapfrogJoin.OPENED.get())
							.as("leapfrog actually opened")
							.isGreaterThan(openedBefore);
					RowCursor observed = opened != null ? opened : plan.open(bound);
					softly.assertThat(observed).as("bound overlap result cursor").isNotNull();
					if (observed != null) {
						softly.assertThat(overlapRows(observed, bound, a, b, c, g))
								.as(opened == null ? "bound fallback result" : "actual leapfrog result")
								.containsExactlyInAnyOrderElementsOf(expected);
					}
				}).as("bound overlap result").doesNotThrowAnyException();
			}).as("bound overlap setup").doesNotThrowAnyException();
		}
		softly.assertAll();
	}

	private static StatementPattern overlapPattern(String subject, String object) {
		return new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS, Var.of(subject),
				Var.of("predicate", FIXED_P, true, true), Var.of(object), Var.of("g"));
	}

	private static List<Map<String, Value>> overlapRows(RowCursor cursor, RowState row, int a, int b, int c, int g)
			throws Exception {
		List<Map<String, Value>> rows = new ArrayList<>();
		try (cursor) {
			while (cursor.next()) {
				rows.add(Map.of("a", row.source.lazyValue(row.slots[a]), "b", row.source.lazyValue(row.slots[b]),
						"c", row.source.lazyValue(row.slots[c]), "g", row.source.lazyValue(row.slots[g])));
			}
		}
		return rows;
	}

	@ParameterizedTest(name = "bound fixed dataset {0}, repeated={1}")
	@CsvSource({ "rdf4j,false", "sesame,false", "both,false", "g1,false", "rdf4j-g1,false",
			"sesame-g1,false", "both-g1,false", "rdf4j,true", "sesame,true", "both,true", "g1,true",
			"rdf4j-g1,true", "sesame-g1,true", "both-g1,true" })
	void fixedDatasetChecksBoundAliasMembership(String selectionName, boolean repeated) throws Exception {
		SimpleDataset selection = membershipDataset(selectionName);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(selection);
		List<BindingSet> inputs = membershipInputs();
		QueryEvaluationStep genericStep = new DefaultEvaluationStrategy(triples, selection, null).precompile(
				membershipPattern(repeated), context);
		SoftAssertions genericChecks = new SoftAssertions();
		for (BindingSet input : inputs) {
			MembershipObservation generic = observeMembership(genericStep, null, input);
			List<Map<String, Value>> expected = membershipExpected(selectionName, repeated, input.getValue("g"));
			System.out.printf("fixed-membership generic selection=%s repeated=%s input=%s result=%s%n",
					selectionName, repeated, input, generic);
			checkMembership(genericChecks, "generic", selectionName, repeated, input, expected, generic);
		}
		genericChecks.assertAll();

		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"fixed dataset bound alias membership", Query.QueryType.TUPLE, "nestedLoop");
		try {
			LmdbNativeEvaluationStrategy strategy = nativeStrategy(selection);
			StatementPattern expression = membershipPattern(repeated);
			mark(expression);
			QueryEvaluationStep step = strategy.precompile(expression, context);
			NativeRowsStep rows = BindingFrameBindings.unframedCapability(step, NativeRowsStep.class);
			NativeBareRowsStep bare = BindingFrameBindings.unframedCapability(step, NativeBareRowsStep.class);
			SlotPlan accepted = rows != null ? rows.arg : bare != null ? bare.arg : null;
			SoftAssertions softly = new SoftAssertions();
			if (accepted != null) {
				softly.assertThat(accepted)
						.as("the accepted physical leaf is a statement pattern")
						.isInstanceOf(PatternPlan.class);
				if (accepted instanceof PatternPlan pattern) {
					softly.assertThat(pattern.contexts.isFixed()).isTrue();
					softly.assertThat(pattern.c.slot).isNotNegative();
					softly.assertThat(pattern.c.slot == pattern.s.slot).isEqualTo(repeated);
				}
			} else {
				System.out.printf("fixed-membership selection=%s repeated=%s physical-leaf=declined step=%s%n",
						selectionName, repeated, step.getClass().getName());
			}
			for (BindingSet input : inputs) {
				MembershipObservation actual = observeMembership(step, expression, input);
				List<Map<String, Value>> expected = membershipExpected(selectionName, repeated, input.getValue("g"));
				System.out.printf("fixed-membership selection=%s repeated=%s input=%s accepted=%s result=%s%n",
						selectionName, repeated, input, accepted != null, actual);
				checkMembership(softly, "native-enabled", selectionName, repeated, input, expected, actual);
				if (accepted != null && !expected.isEmpty()) {
					boolean nativeExecuted = actual.invocations() > 0 && actual.runtime() != null
							&& actual.runtime().contains("executed");
					boolean genericFallback = actual.path() != null && actual.path().contains("genericFallback");
					softly.assertThat(nativeExecuted || genericFallback)
							.as("accepted leaf executed native work or a classified fallback: %s %s %s", selectionName,
									repeated, input)
							.isTrue();
					if (G1.equals(input.getValue("g")) && !GraphFrameBindings.isSupplied(input, "g")) {
						softly.assertThat(nativeExecuted).as("the ordinary G1 input retains native execution").isTrue();
					}
				}
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

